export interface SymbolToken {
  text: string
  quoted: boolean
  /** Offsets of the whole token (quotes included) in the lexed text. */
  start: number
  end: number
}

/** Unquoted words that stand for an empty right-hand side in P. */
export const EPSILON_WORDS = new Set(['ε', 'eps', 'epsilon'])
/** Arrows separating the left and right side of a rule. */
export const ARROWS = ['->', '→', '::=']

// Splits text into symbols separated by whitespace. A token that starts with ' or " and has a closing pair is
// quoted (its content is the symbol, spaces included); a quote anywhere else is an ordinary character (E').
export function lexSymbols(text: string): SymbolToken[] {
  const out: SymbolToken[] = []
  const re = /'([^']*)'|"([^"]*)"|(\S+)/g
  let m: RegExpExecArray | null
  while ((m = re.exec(text))) {
    const quoted = m[3] === undefined
    out.push({ text: quoted ? (m[1] ?? m[2]) : m[3], quoted, start: m.index, end: m.index + m[0].length })
  }
  return out
}

// Removes a trailing comment – an unquoted symbol starting with # starts a comment up to the end of the line
// (`A -> x y  # note`). A quoted '#' stays a symbol, a # inside a symbol (a#b) is part of it.
export function stripComment(line: string) {
  const at = lexSymbols(line).find((t) => !t.quoted && t.text.startsWith('#'))
  return at ? line.slice(0, at.start) : line
}

// Would the bare symbol be read as syntax somewhere (ε-word, alternative, arrow, comment, or an opening quote that
// pairs with a later quote on the same line)?
const isSyntax = (s: string) => EPSILON_WORDS.has(s) || /^['"#|]/.test(s) || ARROWS.some((a) => s.includes(a))

// The shortest spelling of a symbol that lexes back to exactly that symbol in P and in N/T: the bare symbol when it
// is safe, otherwise in '…' or "…". A symbol with whitespace and both quote kinds cannot be written at all.
export function quote(s: string) {
  const candidates = [...(isSyntax(s) ? [] : [s]), `'${s}'`, `"${s}"`]
  const reads = (c: string) => {
    const toks = lexSymbols(c)
    return toks.length === 1 && toks[0].text === s && toks[0].end === c.length
  }
  return candidates.find(reads) ?? `'${s}'`
}

/** All symbols of the text (empty quoted symbols dropped). */
export const symbolList = (text: string) =>
  lexSymbols(text || '')
    .map((t) => t.text)
    .filter((t) => t !== '')
